import { useMemo, useRef, useState } from "react";

export type GraphNode = { id: string; label: string; x: number; y: number };
export type GraphEdge = { from: string; to: string };

export function GraphCanvasNetwork({
  nodes,
  edges,
  width = 640,
  height = 400,
  radius = 18,
}: {
  nodes: GraphNode[];
  edges: GraphEdge[];
  width?: number;
  height?: number;
  radius?: number;
}) {
  const [positions, setPositions] = useState(() =>
    Object.fromEntries(nodes.map((n) => [n.id, { x: n.x, y: n.y }])),
  );
  const [selected, setSelected] = useState<string | null>(null);
  const dragRef = useRef<string | null>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  const neighbours = useMemo(() => {
    if (!selected) return new Set<string>();
    const set = new Set<string>([selected]);
    for (const edge of edges) {
      if (edge.from === selected) set.add(edge.to);
      if (edge.to === selected) set.add(edge.from);
    }
    return set;
  }, [edges, selected]);

  const move = (event: React.PointerEvent<SVGSVGElement>) => {
    const id = dragRef.current;
    const svg = svgRef.current;
    if (!id || !svg) return;
    const box = svg.getBoundingClientRect();
    const x = ((event.clientX - box.left) / box.width) * width;
    const y = ((event.clientY - box.top) / box.height) * height;
    setPositions((prev) => ({ ...prev, [id]: { x, y } }));
  };

  return (
    <svg
      ref={svgRef}
      className="gcn-root"
      viewBox={"0 0 " + width + " " + height}
      role="img"
      aria-label="Dependency graph"
      onPointerMove={move}
      onPointerUp={() => (dragRef.current = null)}
      onPointerLeave={() => (dragRef.current = null)}
    >
      <g className="gcn-edges">
        {edges.map((edge) => {
          const a = positions[edge.from];
          const b = positions[edge.to];
          if (!a || !b) return null;
          const dim =
            selected !== null &&
            (!neighbours.has(edge.from) || !neighbours.has(edge.to));
          return (
            <line
              key={edge.from + "->" + edge.to}
              x1={a.x}
              y1={a.y}
              x2={b.x}
              y2={b.y}
              data-dim={dim}
            />
          );
        })}
      </g>

      <g className="gcn-nodes">
        {nodes.map((node) => {
          const pos = positions[node.id] ?? { x: node.x, y: node.y };
          const dim = selected !== null && !neighbours.has(node.id);
          return (
            <g
              key={node.id}
              className="gcn-node"
              data-selected={node.id === selected}
              data-dim={dim}
              onPointerDown={() => {
                dragRef.current = node.id;
                setSelected(node.id);
              }}
            >
              <circle cx={pos.x} cy={pos.y} r={radius} />
              <text x={pos.x} y={pos.y + radius + 13} textAnchor="middle">
                {node.label}
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );
}

