.gcn-root {
  width: 100%;
  height: auto;
  display: block;
  background: var(--surface-inset, #0a0b10);
  border: 1px solid var(--line-subtle, #1e2230);
  border-radius: 10px;
  touch-action: none;
  background-image: radial-gradient(
    var(--line-subtle, #1e2230) 1px,
    transparent 1px
  );
  background-size: 24px 24px;
}
.gcn-edges line {
  stroke: var(--line-strong, #334155);
  stroke-width: 1.2;
  transition: opacity 0.15s ease, stroke 0.15s ease;
}
.gcn-edges line[data-dim='true'] {
  opacity: 0.18;
}
.gcn-node {
  cursor: grab;
}
.gcn-node circle {
  fill: var(--surface-raised, #171c26);
  stroke: var(--accent, #6366f1);
  stroke-width: 1.5;
  transition: opacity 0.15s ease, transform 0.15s ease;
}
.gcn-node[data-selected='true'] circle {
  fill: var(--accent, #6366f1);
  stroke: #ffffff;
  stroke-width: 2;
}
.gcn-node[data-dim='true'] circle {
  opacity: 0.24;
}
.gcn-node text {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 10px;
  fill: var(--text-muted, #94a3b8);
  user-select: none;
}
.gcn-node[data-dim='true'] text {
  opacity: 0.3;
}
